card_css:
/* Variante 1: Pixelated Flat */
.sl-card {
  background-color: var(--sl-card-bg);
  color: var(--sl-text-main);
  border: 2px solid var(--sl-primary);
  border-radius: 0;
  box-shadow: 4px 4px 0px 0px var(--sl-primary);
  transition: transform 0.1s ease-out, box-shadow 0.1s ease-out;
}
.sl-card:hover {
  transform: translate(-2px, -2px);
  box-shadow: 6px 6px 0px 0px var(--sl-primary);
}

/* Variante 2: Neon Glow */
.sl-card {
  background-color: var(--sl-card-bg);
  color: var(--sl-text-main);
  border: 1px solid var(--sl-primary);
  border-radius: 0.25rem;
  box-shadow: 0 0 5px var(--sl-primary), 0 0 10px var(--sl-primary) inset;
  transition: box-shadow 0.3s ease-in-out, border-color 0.3s ease-in-out, transform 0.1s ease-out;
}
.sl-card:hover {
  border-color: var(--sl-primary);
  box-shadow: 0 0 10px var(--sl-primary), 0 0 20px var(--sl-primary), 0 0 30px var(--sl-primary) inset;
  transform: translateY(-2px);
}

/* Variante 3: 8-bit Border Outline */
.sl-card {
  background-color: var(--sl-card-bg);
  color: var(--sl-text-main);
  border: none;
  outline: 4px solid var(--sl-primary);
  outline-offset: -2px;
  border-radius: 0;
  box-shadow: 8px 8px 0px 0px var(--sl-primary);
  transition: box-shadow 0.15s ease-out, outline-offset 0.15s ease-out, transform 0.15s ease-out;
}
.sl-card:hover {
  transform: translate(-4px, -4px);
  box-shadow: 12px 12px 0px 0px var(--sl-primary);
  outline-offset: -4px;
}

/* Variante 4: CRT Scanline Effect */
.sl-card {
  background-color: var(--sl-card-bg);
  color: var(--sl-text-main);
  border: 2px solid var(--sl-primary);
  border-radius: 0.75rem;
  overflow: hidden;
  position: relative;
  box-shadow: 0 0 10px rgba(0,0,0,0.5);
  transition: transform 0.2s ease-in-out, box-shadow 0.2s ease-in-out;
}
.sl-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(rgba(0, 0, 0, 0.1) 50%, transparent 50%);
  background-size: 100% 2px;
  pointer-events: none;
}
.sl-card:hover {
  transform: scale(1.02);
  box-shadow: 0 0 15px var(--sl-primary), 0 0 25px rgba(0,0,0,0.7);
}

/* Variante 5: Glitch Distorted */
.sl-card {
  background-color: var(--sl-card-bg);
  color: var(--sl-text-main);
  border: 2px solid var(--sl-primary);
  border-radius: 0;
  position: relative;
  overflow: hidden;
  box-shadow: 4px 4px 0px 0px var(--sl-primary), -4px -4px 0px 0px rgba(255, 255, 255, 0.1);
  transition: transform 0.1s linear, box-shadow 0.1s linear;
}
.sl-card::before {
  content: '';
  position: absolute;
  top: 4px; left: 4px;
  width: calc(100% - 8px);
  height: calc(100% - 8px);
  border: 1px dotted var(--sl-text-main);
  opacity: 0.3;
  pointer-events: none;
}
.sl-card:hover {
  transform: translate(1px, -1px);
  box-shadow: 6px -2px 0px 0px var(--sl-primary), -2px 6px 0px 0px var(--sl-primary);
  border-color: var(--sl-text-main);
}

/* Variante Nova 1: Retro Arcade Button (Skeuomorphic/Pop-Retro) */
.sl-card {
  background: linear-gradient(135deg, var(--sl-card-bg) 0%, darken(var(--sl-card-bg), 10%) 100%);
  border-radius: 6px;
  box-shadow:
    inset 0 -4px 0 rgba(0,0,0,0.3),
    inset 0 4px 0 rgba(255,255,255,0.2),
    0 8px 0 var(--sl-primary),
    0 10px 15px rgba(0,0,0,0.4);
  transform: translateY(0);
  transition: all 0.1s ease-out;
  cursor: pointer;
  color: var(--sl-text-main);
}
.sl-card:hover {
  transform: translateY(4px);
  box-shadow:
    inset 0 -2px 0 rgba(0,0,0,0.3),
    inset 0 2px 0 rgba(255,255,255,0.2),
    0 4px 0 var(--sl-primary),
    0 6px 10px rgba(0,0,0,0.4);
}

/* Variante Nova 2: 8-bit Game Cartridge (Skeuomorphic/Layered) */
.sl-card {
  position: relative;
  background-color: var(--sl-card-bg);
  border-radius: 4px 4px 0 0;
  box-shadow: 0 6px 0 var(--sl-primary), 0 8px 15px rgba(0,0,0,0.3);
  padding-top: 20px; /* Space for the 'lip' */
  color: var(--sl-text-main);
}
.sl-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 16px; /* Cartridge 'lip' height */
  background-color: var(--sl-primary);
  border-radius: 4px 4px 0 0;
  box-shadow: inset 0 2px 0 rgba(255,255,255,0.2), inset 0 -2px 0 rgba(0,0,0,0.3);
}

/* Variante Nova 3: Pixel Terminal Frosted (Tech UI/Frosted) */
.sl-card {
  background-color: rgba(var(--sl-bg-body-rgb), 0.8);
  border: 2px solid var(--sl-primary);
  box-shadow: 0 0 15px rgba(var(--sl-primary-rgb), 0.6), inset 0 0 8px rgba(var(--sl-primary-rgb), 0.3);
  backdrop-filter: blur(4px) brightness(80%); /* Pixelated blur implied */
  -webkit-backdrop-filter: blur(4px) brightness(80%);
  border-radius: 0;
  color: var(--sl-text-main);
  font-family: 'Press Start 2P', monospace; /* Suggest a retro font */
}

/* Variante Nova 4: Pop-Art Comic Panel (Editorial/Geometric) */
.sl-card {
  background-color: var(--sl-card-bg);
  border: 4px solid var(--sl-text-main);
  box-shadow: 8px 8px 0 var(--sl-primary), 12px 12px 0 darken(var(--sl-primary), 20%); /* Layered offset shadows */
  border-radius: 0;
  color: var(--sl-text-main);
  position: relative;
  overflow: hidden;
}
.sl-card::after {
  content: '';
  position: absolute;
  top: -10%;
  left: -10%;
  width: 120%;
  height: 120%;
  background-image: radial-gradient(circle, rgba(var(--sl-primary-rgb),0.3) 1px, transparent 1px);
  background-size: 8px 8px;
  opacity: 0.1;
  z-index: 0;
}

/* Variante Nova 5: Data Block / Glitch-Free Tech (Brutalist Minimal/Structured) */
.sl-card {
  background-color: var(--sl-card-bg);
  border-radius: 0;
  border: 1px solid var(--sl-text-main);
  box-shadow: inset 0 0 0 2px var(--sl-primary),
              0 4px 8px rgba(0,0,0,0.2);
  color: var(--sl-text-main);
  position: relative;
  overflow: hidden;
}
.sl-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: repeating-linear-gradient(45deg, rgba(var(--sl-primary-rgb),0.05) 0 1px, transparent 1px 10px);
  z-index: 0;
  pointer-events: none;
}
